def is_valid_sudoku(grid):
    """
    Determine whether a Sudoku board is valid according to the rules:
    - Each row must contain digits 1–9 without repetition (zeros are ignored).
    - Each column must contain digits 1–9 without repetition (zeros are ignored).
    - Each 3×3 subgrid must contain digits 1–9 without repetition (zeros are ignored).

    Parameters
    ----------
    grid : list[list[int]]
        A 9×9 grid. Each element may be an integer between 0 and 9.
        Zeros represent unfilled cells.

    Returns
    -------
    bool
        True if the board is valid, False otherwise.
    """
    if len(grid) != 9 or any(len(row) != 9 for row in grid):
        return False

    # Helper to filter out zeros from a sequence
    def nonzero(seq):
        return [x for x in seq if x != 0]

    # Check rows
    for row in grid:
        seen = set()
        for num in nonzero(row):
            if num in seen:
                return False
            seen.add(num)

    # Check columns
    for col in range(9):
        seen = set()
        for row in grid:
            if row[col] != 0:
                if row[col] in seen:
                    return False
                seen.add(row[col])

    # Check 3×3 subgrids
    for block_row in range(0, 9, 3):
        for block_col in range(0, 9, 3):
            seen = set()
            for r in range(block_row, block_row + 3):
                for c in range(block_col, block_col + 3):
                    if grid[r][c] != 0:
                        if grid[r][c] in seen:
                            return False
                        seen.add(grid[r][c])

    return True

import sys
import json

def main():
    try:
        input_line = sys.stdin.readline().strip()
        data = json.loads(input_line)
    except Exception as e:
        sys.stderr.write(f"Error reading input: {e}\n")
        sys.exit(1)

    if not data:
        print('<table></table>')
        return

    headers = set()
    for row in data:
        headers.update(row.keys())
    headers = list(headers)

    print('<table border="1">')
    print('<tr>')
    for header in headers:
        print(f'<th>{header}</th>')
    print('</tr>')

    for row in data:
        print('<tr>')
        for header in headers:
            value = row.get(header)
            if value is None:
                value = 'N/A'
            print(f'<td>{value}</td>')
        print('</tr>')

    print('</table>')

if __name__ == "__main__":
    main()

